from lib import *
S = SS('w27')
steps = [
    step("双栈套接字:net.inet6.ip6.v6only = 0(默认双栈)。监听 :: 且 IPV6_V6ONLY=0 的服务端,既能收 ::1 的连接(对端地址 ::1),也能收 127.0.0.1 的连接,这时对端地址显示成 IPv4 映射地址 ::ffff:127.0.0.1(Python 的 ipv4_mapped 取出 127.0.0.1)。把 IPV6_V6ONLY 设成 1,连 ::1 仍然成功,连 127.0.0.1 变成 ConnectionRefusedError——只服务 IPv6。所以一个 AF_INET6 的监听套接字在默认设置下可以同时服务两种协议。", t=tl(S(1)), mark=lidx(S(1), 'IPV6_V6ONLY=0:', 'IPV6_V6ONLY=1:'), done=lidx(S(1), 'net.inet6.ip6.v6only', 'IPv4 映射地址'), kv=KV([['V6ONLY=0', '连 ::1 和 127.0.0.1 都成功'], ['IPv4 客户端的地址', '::ffff:127.0.0.1(映射地址)'], ['V6ONLY=1', '连 127.0.0.1 被拒绝']], ['IPv4 客户端的地址'])),
    step("getaddrinfo(\"localhost\") 返回的顺序:IPv6 ::1 在前,IPv4 127.0.0.1 在后,默认和加 AI_ADDRCONFIG 都一样。按 RFC 6724 的默认策略 IPv6 优先,应用按这个顺序一个个尝试:先试 ::1,失败(被拒绝)再试 127.0.0.1。这一步被拒绝是瞬间的,所以用户察觉不到;但如果 IPv6 那一项是“挂住”而不是“被拒绝”,后果就大不一样(下面两节)。", t=tl(S(2)), mark=lidx(S(2), '默认:', 'AI_ADDRCONFIG:'), done=lidx(S(2), '按 RFC 6724'), kv=KV([['顺序', 'IPv6 ::1 → IPv4 127.0.0.1'], ['策略', 'RFC 6724:IPv6 优先'], ['被拒绝', '瞬间回退,感觉不到'], ['挂住', '要等到超时,才试下一个']], ['挂住'])),
    step("IPv6 一端很慢时的代价:IPv6 监听在 netlab 作用的端口(每个方向 400 ms 延迟,一次 SYN / SYN-ACK 往返约 800 ms),IPv4 监听在不受影响的端口。基线(没有延迟)顺序连接(IPv6 先)用时中位 0.10 ms,Happy Eyeballs 0.12 ms,5 次里 IPv6 赢了 5 次。加延迟后:顺序连接要等 IPv6 连上,用时中位 801 ms;Happy Eyeballs(IPv6 先发,250 ms 后启动 IPv4)用时中位 255 ms,5 次里 IPv4 赢了 5 次。Happy Eyeballs 不是放弃 IPv6:IPv6 本来就快时它赢了;只有 IPv6 太慢才让 IPv4 去抢。", t=tl(S(3)), mark=lidx(S(3), '没有延迟时(基线)', 'IPv6 加了 400 ms', 'Happy Eyeballs(250 ms'), done=lidx(S(3), 'Happy Eyeballs 不是放弃'), b=bars([['顺序回退(IPv6 先)', 801, '801 ms'], ['Happy Eyeballs 250 ms', 255, '255 ms'], ['基线 · 顺序', 0.10, '0.10 ms'], ['基线 · Happy Eyeballs', 0.12, '0.12 ms']], 801, mark=[0, 1], done=[2, 3]), kv=KV([['IPv6 慢(往返 800 ms)', '顺序回退 801 ms'], ['Happy Eyeballs', '255 ms,IPv4 赢 5/5'], ['IPv6 正常', 'Happy Eyeballs 0.12 ms,IPv6 赢 5/5']], ['Happy Eyeballs'])),
    step("IPv6 是黑洞时(真实的):目标是本链路上一个不存在的链路本地地址,邻居解析不出来,TCP 的 SYN 一直发不出去(前面单独试过,connect 挂了 20 秒以上)。用 asyncio 的 create_connection,把 getaddrinfo 换成“IPv6 黑洞 + 127.0.0.1”两项:happy_eyeballs_delay=None(关闭)时,2 次都卡到我设的 5 秒上限(TimeoutError),一直没轮到 IPv4;打开 happy_eyeballs_delay=0.25 时,3 次分别在 254、253、252 ms 连上 127.0.0.1——250 ms 后启动 IPv4,立刻成功。", t=tl(S(4)), mark=lidx(S(4), 'happy_eyeballs_delay=0.25'), done=lidx(S(4), 'happy_eyeballs_delay=None'), b=bars([['关闭 · 等到上限', 5000, '5000 ms 超时'], ['打开 0.25 · 连上用时', 254, '254 ms']], 5000, mark=[0], done=[1]), kv=KV([['IPv6 黑洞', 'SYN 发不出去,connect 一直挂着'], ['happy_eyeballs_delay=None', '卡死在 IPv6 上(5 秒上限)'], ['happy_eyeballs_delay=0.25', '254 ms 内连上 IPv4']], ['happy_eyeballs_delay=None'])),
    step("启动延迟取不同的值,黑洞时连上的用时(asyncio,每个值 3 次取中位):0.05 → 52 ms,0.1 → 102 ms,0.25 → 252 ms,0.5 → 502 ms,1.0 → 1004 ms;连上用时就是延迟值加 2~4 ms 的额外开销。所以这个延迟就是“IPv6 出问题时用户多等多久”的上限;设得太小,IPv6 稍慢就会被 IPv4 抢走(浪费连接,偏向 IPv4),设得太大则黑洞时等得久。RFC 8305 建议:先解析 AAAA,A 记录最多再等 50 ms 的解析延迟;连接尝试延迟默认 250 ms,可以根据历史 RTT 在 100 ms 到 2 s 之间调整。", t=tl(S(5)), mark=lidx(S(5), 'happy_eyeballs_delay=0.25', 'RFC 8305'), done=lidx(S(5), 'happy_eyeballs_delay=0.05', 'happy_eyeballs_delay=0.1 ', 'happy_eyeballs_delay=0.5', 'happy_eyeballs_delay=1.0'), b=bars([['延迟 0.05 s', 52, '52 ms'], ['延迟 0.1 s', 102, '102 ms'], ['延迟 0.25 s', 252, '252 ms'], ['延迟 0.5 s', 502, '502 ms'], ['延迟 1.0 s', 1004, '1004 ms']], 1004, mark=[2], done=[0, 1, 3, 4]), kv=KV([['连上用时', '≈ 延迟值 + 2~4 ms'], ['推荐值', '250 ms(RFC 8305)'], ['范围', '100 ms ~ 2 s']], ['推荐值'])),
]
A = mkartw('w27', 27, '网络协议,双栈,Happy Eyeballs,IPv6,IPv4映射地址,getaddrinfo,asyncio,真实验证,动画演示',
    'IPV6_V6ONLY=0 的双栈监听同时服务 ::1 与 127.0.0.1;IPv6 一端慢(往返 800 ms)时顺序回退 801 ms,Happy Eyeballs 255 ms;真实的 IPv6 黑洞上 asyncio 关闭 Happy Eyeballs 卡死、打开 0.25 则 254 ms 连上 IPv4;延迟值就是额外等待上限。',
    'IPv4 和 IPv6 并存的时候,应用先连哪个?IPv6 连不通为什么会让整个网页卡几十秒?Happy Eyeballs 的 250 毫秒是怎么回事?这篇用 netlab 给 IPv6 加延迟、用一个真实的 IPv6 黑洞地址,实测顺序回退与 Happy Eyeballs 的差别。',
    [('801 ms → 255 ms', 'IPv6 往返 800 ms 时,顺序回退与 Happy Eyeballs(250 ms)的连接用时'), ('5 秒仍卡死', 'IPv6 黑洞时 asyncio 关闭 Happy Eyeballs 的结果;打开 0.25 则 254 ms 连上 IPv4'), ('+2~4 ms', '每个 Happy Eyeballs 延迟值之上的额外开销:连上用时就是延迟值加这一点')],
    [('双栈', '<p>监听 :: 的 AF_INET6 套接字默认同时收 IPv4 与 IPv6,IPv4 客户端以 ::ffff:a.b.c.d 的映射地址出现;IPV6_V6ONLY=1 则只收 IPv6。</p>'),
     ('地址顺序', '<p>getaddrinfo 按 RFC 6724 把 IPv6 排在前面,应用依次尝试。被拒绝时瞬间回退,而地址挂住时每一项都要等到超时。</p>'),
     ('IPv6 慢', '<p>往返 800 ms 的 IPv6 让顺序回退花 801 ms;Happy Eyeballs 在 IPv6 起步 250 ms 后并行启动 IPv4,用时 255 ms。IPv6 正常时 IPv6 照样赢。</p>'),
     ('IPv6 黑洞', '<p>目标是不存在的链路本地地址时,SYN 发不出去。asyncio 关闭 Happy Eyeballs 卡死,打开 0.25 就在 254 ms 内连上 IPv4。</p>'),
     ('延迟值', '<p>延迟值就是黑洞时用户多等的时间上限(实测连上用时 = 延迟 + 2~4 ms)。RFC 8305 建议 250 ms,可在 100 ms 到 2 s 之间调整。</p>')],
    steps,
    [ENV_W + '。本机网络没有公网 IPv6,所以“IPv6 慢”由 netlab 在 lo0 上对 ::1 的端口加延迟模拟,“IPv6 黑洞”是对一个不存在的链路本地地址的真实 TCP 连接;顺序回退与 Happy Eyeballs 的线程实现是自己写的简化版,asyncio 部分用 getaddrinfo 的替换函数喂入“黑洞 + 127.0.0.1”两项',
     '没有验证:公网上的真实双栈主机;系统解析器并行查询 A / AAAA 的“解析延迟”;浏览器与 curl 的 Happy Eyeballs 实现(版本 2 的历史 RTT 记忆等);IPv6 连通但路径 MTU 黑洞的情形;macOS 的 getaddrinfo 在有全球 IPv6 地址时的排序'],
    '双栈与 Happy Eyeballs')
